namespace VeraCue.Api.Entities;

/// <summary>A reusable set of QA criteria that a manager defines (table: QaTemplates).</summary>
public class QaTemplate
{
    /// <summary>Generated by the app. Version 7 GUIDs are time-ordered, which keeps indexes compact.</summary>
    public Guid Id { get; set; } = Guid.CreateVersion7();

    public required string Name { get; set; }

    public string? Description { get; set; }

    /// <summary>Templates are archived instead of deleted, so past evaluations keep their template.</summary>
    public bool IsArchived { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime UpdatedAt { get; set; }

    public List<QaCriterion> Criteria { get; set; } = [];
}
